🗃️ The Dataset We'll Use Throughout
Let's set up two tables and keep them consistent across every example. This way, when something changes between queries, you know exactly why. CREATE TABLE employees ( emp_id INT PRIMARY KEY, full_name VARCHAR(100), dept_id INT, salary DECIMAL(10,2), hire_date DATE );
INSERT INTO employees VALUES (1, 'Alice Mensah', 1, 72000, '2020-03-15'), (2, 'Brian Okonkwo', 2, 58000, '2021-07-01'), (3, 'Carol Wanjiku', 1, 65000, '2019-11-20'), (4, 'David Kimani', NULL, 49000, '2023-01-10'), -- no department assigned (5, 'Evelyn Njoroge', 3, 91000, '2018-06-05');
CREATE TABLE departments ( dept_id INT PRIMARY KEY, dept_name VARCHAR(100), location VARCHAR(100) );
